    local TbCMapBase = function()
        ---@class TbCMapBase
        ---@field public AllTables CfgC.MapBase[] 全部配置
        ---@field public AllKeys table<string, integer> 全部Key
        local t = {
            AllTables = {},
            AllKeys = {},
        }
        parseTable(t,
            {
                "Id",
            },
            require("cfgc_tbcmapbase.lua")
        )

        ---@param Id integer @地图Id
        ---@return CfgC.MapBase?
        function t:GetData(Id,...)
            local tKey = {
                Id,
            }
            local key = combineKey(tKey)

            if self.AllKeys[key] == nil then
                return nil
            end

            return self.AllTables[self.AllKeys[key]]
        end

        return t
    end
